 const regions=[['all','Усе рэгіёны','Все регионы'],['brest','Брэсцкая вобласць','Брестская область'],['vitebsk','Віцебская вобласць','Витебская область'],['gomel','Гомельская вобласць','Гомельская область'],['grodno','Гродзенская вобласць','Гродненская область'],['minsk','Мінская вобласць','Минская область'],['mogilev','Магілёўская вобласць','Могилёвская область']];
