    $('#saveHeritageReportLetter').onclick=()=>{const typed=$('#heritageReportDraft').value.trim();if(!typed){toast(T('Спачатку падрыхтуйце тэкст паведамлення.','Сначала подготовьте текст сообщения.'));return}const title=(typed.split('\n')[0]||T('Паведамленне пра стан','Сообщение о состоянии'));const letter=upsertUserLetter({id:reportLetterId,title,kind:'report',text:typed});reportLetterId=letter.id;reportText=typed;$('#emailHeritageReport').href=`mailto:vikashyshko777@gmail.com?subject=${encodeURIComponent(title)}&body=${encodeURIComponent(typed)}`;toast(T('Ліст захаваны ў копілцы. Яго можна змяніць або выдаліць.','Письмо сохранено в копилке. Его можно изменить или удалить.'))};
