  guideRouteGrid?.addEventListener('click',e=>{const b=e.target.closest('[data-open-route]');if(b){openGuideRoute(b.dataset.openRoute);return}const card=e.target.closest('.guide-itinerary-card');if(card&&!e.target.closest('button,a,summary,details')){const open=card.querySelector('[data-open-route]');if(open)openGuideRoute(open.dataset.openRoute)}});
  const routeKindFilter=$('#routeKindFilter'),routeRegionFilter=$('#routeRegionFilter'),routeCategoryFilter=$('#routeCategoryFilter'),routeFilterCount=$('#routeFilterCount');
  function applyGuideFilters(){
   if(!guideRouteGrid)return;
   const kind=routeKindFilter?.value||'all',region=routeRegionFilter?.value||'all',category=routeCategoryFilter?.value||'all';let shown=0;
   guideRouteGrid.querySelectorAll('.guide-itinerary-card').forEach(card=>{
    const categories=(card.dataset.routeCategories||'').split(/\s+/);
    const matches=(kind==='all'||card.dataset.routeKind===kind)&&(region==='all'||(card.dataset.routeRegions||'').split(/\s+/).includes(region))&&(category==='all'||categories.includes(category));
    card.classList.toggle('hidden',!matches);if(matches)shown++;
   });
   if(routeFilterCount)routeFilterCount.textContent=T(`Паказана падборак: ${shown}.`,`Подборок показано: ${shown}.`);
  }
