  $('#clearRouteFilters')?.addEventListener('click',()=>{if(routeKindFilter)routeKindFilter.value='all';if(routeRegionFilter)routeRegionFilter.value='all';if(routeCategoryFilter)routeCategoryFilter.value='all';document.querySelectorAll('.route-filter-highlight').forEach(x=>x.classList.remove('route-filter-highlight'));applyGuideFilters()});
